# GENERATED by scripts/sync_seasonals.py from grain-seasonal-dashboard/app.py. Do not edit here: change the source app (or the transform) and re-run `python scripts/sync_seasonals.py apply`.
"""Trends snapshot maths: price changes, simple moving averages and a seasonal read for a
futures contract. Pure functions on settlement histories (no Streamlit), so they can be
checked on their own.

Seasonal read. For each of the last SEASONAL_YEARS years, take the SAME contract month (the
Dec contract of the year before, and so on) and measure its move over the same calendar
window from today's date: the settlement on today's date shifted back k years against the
settlement HORIZON_DAYS later. The average of those moves sets the read:

    Higher   average move of +3% or more
    Weaker   average move of -3% or less
    Neutral  anything inside +/-3%

The years column counts how many individual years finished above +3%, inside the band and
below -3%, so a read that rests on one wild year is visible as such.
"""
from __future__ import annotations

from dataclasses import dataclass
from datetime import date, timedelta

import pandas as pd

SEASONAL_YEARS = 15
HORIZON_DAYS = 30          # "the next month"
MIN_HORIZON_DAYS = 10      # a contract about to expire has no month ahead to read
MIN_SEASONAL_YEARS = 3     # fewer years than this is an anecdote, not a seasonal
NEUTRAL_BAND = 0.03        # +/-3% of the current price counts as neutral
SMA_WINDOWS = (20, 100, 200)

# (label, how far back) for the price-change columns.
LOOKBACKS = (
    ("1 week", {"days": 7}),
    ("1 month", {"months": 1}),
    ("1 year", {"years": 1}),
)
REFERENCE_GAP_DAYS = 7     # nearest earlier settlement may be at most this far before the target
SEASONAL_GAP_DAYS = 5      # same, for the seasonal window's two end points


@dataclass(frozen=True)
class SeasonalRead:
    label: str | None      # "Higher" / "Neutral" / "Weaker"; None when too few years to call
    average: float         # mean move over the horizon, as a fraction
    years: int             # years that had data for the window
    higher: int
    neutral: int
    weaker: int


@dataclass(frozen=True)
class ContractTrend:
    ticker: str
    expiration: date
    last: float
    changes: dict[str, tuple[float, float] | None]   # label -> (change, change as a fraction)
    averages: dict[int, float | None]                # window -> simple moving average
    seasonal: SeasonalRead | None
    horizon_days: int


def clean(series: pd.Series | None) -> pd.Series:
    """Ascending, one value per day, on a DatetimeIndex (histories arrive keyed by date)."""
    if series is None or not len(series):
        return pd.Series(dtype=float)
    out = series[~series.index.duplicated(keep="last")].sort_index().astype(float)
    out.index = pd.to_datetime(out.index)
    return out


def shift_back(when: date, years: int = 0, months: int = 0, days: int = 0) -> date:
    """Calendar shift that clips to month end (Feb 29 less a year is Feb 28)."""
    return (pd.Timestamp(when) - pd.DateOffset(years=years, months=months, days=days)).date()


def price_on_or_before(series: pd.Series, when: date,
                       max_gap_days: int) -> tuple[date, float] | None:
    """The last settlement on or before `when`, unless it is more than max_gap_days older.
    `series` must already be clean()ed."""
    if not len(series):
        return None
    target = pd.Timestamp(when)
    pos = series.index.searchsorted(target, side="right") - 1
    if pos < 0:
        return None
    found = series.index[pos]
    if (target - found).days > max_gap_days:
        return None
    return found.date(), float(series.iloc[pos])


def price_changes(history: pd.Series, last: float,
                  as_of: date) -> dict[str, tuple[float, float] | None]:
    """{label: (change, fraction)} of `last` against the settlement a week, month and year
    before `as_of`. None where the contract had no settlement near that date (it was not
    listed yet)."""
    out: dict[str, tuple[float, float] | None] = {}
    for label, offset in LOOKBACKS:
        ref = price_on_or_before(history, shift_back(as_of, **offset), REFERENCE_GAP_DAYS)
        if ref is None or ref[1] <= 0:
            out[label] = None
        else:
            out[label] = (last - ref[1], last / ref[1] - 1)
    return out


def simple_average(history: pd.Series, window: int) -> float | None:
    """Mean of the last `window` daily settlements, or None if there are not that many."""
    if len(history) < window:
        return None
    return float(history.iloc[-window:].mean())


def horizon_for(as_of: date, expiration: date | None) -> int:
    """30 days, or fewer when the contract expires first (it can only be read to expiry)."""
    if expiration is None:
        return HORIZON_DAYS
    return min(HORIZON_DAYS, (expiration - as_of).days)


def analog_years(expiration: date, years: int = SEASONAL_YEARS) -> list[tuple[int, int]]:
    """[(years_back, contract_year)] for the same contract month in the years before this one."""
    return [(k, expiration.year - k) for k in range(1, years + 1)]


def seasonal_moves(analogs: dict[int, pd.Series], as_of: date,
                   horizon_days: int) -> dict[int, float]:
    """{years_back: fractional move over the window} for each analog contract that has a
    settlement at both ends of it. `analogs` maps years_back to that year's history."""
    moves: dict[int, float] = {}
    for years_back, raw in analogs.items():
        series = clean(raw)
        if len(series) < 2:
            continue
        start = shift_back(as_of, years=years_back)
        end = start + timedelta(days=horizon_days)
        first = price_on_or_before(series, start, SEASONAL_GAP_DAYS)
        last = price_on_or_before(series, end, SEASONAL_GAP_DAYS)
        if first is None or last is None or last[0] <= first[0] or first[1] <= 0:
            continue
        moves[years_back] = last[1] / first[1] - 1
    return moves


def seasonal_read(moves: dict[int, float]) -> SeasonalRead | None:
    """Turn the per-year moves into a Higher / Neutral / Weaker call."""
    if not moves:
        return None
    values = list(moves.values())
    average = sum(values) / len(values)
    higher = sum(v >= NEUTRAL_BAND for v in values)
    weaker = sum(v <= -NEUTRAL_BAND for v in values)
    label = None
    if len(values) >= MIN_SEASONAL_YEARS:
        label = ("Higher" if average >= NEUTRAL_BAND
                 else "Weaker" if average <= -NEUTRAL_BAND else "Neutral")
    return SeasonalRead(label, average, len(values), higher,
                        len(values) - higher - weaker, weaker)


def contract_trend(ticker: str, expiration: date, last: float, history: pd.Series | None,
                   analogs: dict[int, pd.Series], as_of: date) -> ContractTrend:
    """Everything the snapshot shows for one contract."""
    history = clean(history)
    horizon = horizon_for(as_of, expiration)
    seasonal = None
    if horizon >= MIN_HORIZON_DAYS:
        seasonal = seasonal_read(seasonal_moves(analogs, as_of, horizon))
    return ContractTrend(
        ticker=ticker,
        expiration=expiration,
        last=last,
        changes=price_changes(history, last, as_of),
        averages={w: simple_average(history, w) for w in SMA_WINDOWS},
        seasonal=seasonal,
        horizon_days=horizon,
    )
